:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8fa3;
  --win: #4ecca3;
  --lose: #e94560;
  --draw: #f5c542;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: var(--bg);
  background-image: radial-gradient(circle at 20% 20%, #23234a 0%, transparent 40%),
                    radial-gradient(circle at 80% 80%, #2a1a3e 0%, transparent 40%);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
}

.game-card {
  width: 100%;
  max-width: 520px;
  background: var(--card);
  border: 4px solid #0f0f1a;
  border-radius: 12px;
  padding: 24px 20px;
  box-shadow: 0 8px 0 #0f0f1a, 0 12px 30px rgba(0,0,0,0.5);
  text-align: center;
}

h1 {
  font-size: 1.4rem;
  margin: 0 0 16px;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 #0f0f1a;
}

.scoreboard {
  display: flex;
  justify-content: space-around;
  gap: 12px;
  margin-bottom: 20px;
}

.score {
  flex: 1;
  background: #0f0f1a;
  border-radius: 8px;
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.score .label {
  font-size: 0.85rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.score .value {
  font-size: 1.8rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.arena {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-bottom: 16px;
}

.choice-box {
  flex: 1;
  background: #0f0f1a;
  border-radius: 8px;
  padding: 12px 4px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.box-label {
  font-size: 0.8rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.pixel-icon {
  font-size: 2.4rem;
  line-height: 1.2;
  image-rendering: pixelated;
}

.vs {
  font-weight: 700;
  color: var(--muted);
  font-size: 0.9rem;
}

.result {
  min-height: 1.5em;
  font-size: 1.1rem;
  font-weight: 600;
  margin: 0 0 20px;
  transition: color 0.2s;
}

.result.win { color: var(--win); }
.result.lose { color: var(--lose); }
.result.draw { color: var(--draw); }

.controls {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-bottom: 16px;
}

.choice-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 12px 4px;
  font-size: 1.6rem;
  font-family: inherit;
  color: var(--text);
  background: #23234a;
  border: 3px solid #0f0f1a;
  border-radius: 10px;
  cursor: pointer;
  box-shadow: 0 4px 0 #0f0f1a;
  transition: transform 0.08s, background 0.15s, box-shadow 0.08s;
}

.choice-btn span {
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.choice-btn:hover { background: #2e2e5e; }
.choice-btn:active {
  transform: translateY(3px);
  box-shadow: 0 1px 0 #0f0f1a;
}
.choice-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.reset-btn {
  width: 100%;
  padding: 12px;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #fff;
  background: var(--accent);
  border: 3px solid #0f0f1a;
  border-radius: 10px;
  cursor: pointer;
  box-shadow: 0 4px 0 #0f0f1a;
  transition: transform 0.08s, background 0.15s, box-shadow 0.08s;
}

.reset-btn:hover { background: #ff5c78; }
.reset-btn:active {
  transform: translateY(3px);
  box-shadow: 0 1px 0 #0f0f1a;
}
.reset-btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

@media (max-width: 380px) {
  .game-card { padding: 20px 14px; }
  .pixel-icon { font-size: 2rem; }
  .choice-btn { font-size: 1.3rem; }
  .choice-btn span { font-size: 0.75rem; }
}

const MOVES = ['rock', 'paper', 'scissors'];
const EMOJI = { rock: '✊', paper: '✋', scissors: '✌️' };

const playerScoreEl = document.getElementById('player-score');
const computerScoreEl = document.getElementById('computer-score');
const playerChoiceEl = document.getElementById('player-choice');
const computerChoiceEl = document.getElementById('computer-choice');
const resultEl = document.getElementById('result');

let playerScore = 0;
let computerScore = 0;

function getComputerMove() {
  return MOVES[Math.floor(Math.random() * MOVES.length)];
}

function getWinner(player, computer) {
  if (player === computer) return 'draw';
  const wins = { rock: 'scissors', paper: 'rock', scissors: 'paper' };
  return wins[player] === computer ? 'player' : 'computer';
}

function playRound(playerMove) {
  const computerMove = getComputerMove();
  playerChoiceEl.textContent = EMOJI[playerMove];
  computerChoiceEl.textContent = EMOJI[computerMove];

  const winner = getWinner(playerMove, computerMove);
  resultEl.classList.remove('win', 'lose', 'draw');

  if (winner === 'draw') {
    resultEl.textContent = "It's a draw!";
    resultEl.classList.add('draw');
  } else if (winner === 'player') {
    playerScore++;
    playerScoreEl.textContent = playerScore;
    resultEl.textContent = `You win! ${EMOJI[playerMove]} beats ${EMOJI[computerMove]}`;
    resultEl.classList.add('win');
  } else {
    computerScore++;
    computerScoreEl.textContent = computerScore;
    resultEl.textContent = `CPU wins! ${EMOJI[computerMove]} beats ${EMOJI[playerMove]}`;
    resultEl.classList.add('lose');
  }
}

function resetGame() {
  playerScore = 0;
  computerScore = 0;
  playerScoreEl.textContent = '0';
  computerScoreEl.textContent = '0';
  playerChoiceEl.textContent = '❔';
  computerChoiceEl.textContent = '❔';
  resultEl.textContent = 'Choose your move!';
  resultEl.classList.remove('win', 'lose', 'draw');
}

document.querySelectorAll('.choice-btn').forEach((btn) => {
  btn.addEventListener('click', () => playRound(btn.dataset.move));
});

document.getElementById('reset-btn').addEventListener('click', resetGame);
